head.script:
// 원본 : ULDSTF05403 (팝업)수익증권 신규상장관리 (/ui/sample/template/ULDSTF05403.xml)

/*
 * 화면 동작
 * 1. 팝업 로딩시 공통코드(투자기구종류)를 채우고, 부모가 넘긴 업무처리번호가 있으면 상세를 조회
 * 2. 「종목코드」 돋보기 클릭시 수익증권 종목 선택 팝업 호출 → 예비심사 정보를 조회해 폼을 채움
 * 3. 「수탁회사」·「사무관리회사」 돋보기 클릭시 기관·법인 선택 팝업 호출
 * 4. 「저장」 클릭시 입력값 검증 → 중복입력 확인 → 확인 → 업무처리번호 채번 → 저장
 *    「수정」 클릭시 입력값 검증 → 확인 → 수정
 * 5. 저장·수정 후 부모 목록을 재조회하고 상세를 다시 조회해 버튼 상태를 맞춤
 *
 * 담긴 패턴
 * - 부모 파라미터 수신 ($c.data.getParameter) 과 부모 화면 함수 호출 ($c.win.getParent)
 * - 공통코드 셀렉트박스 ($c.data.setCommonCode)
 * - 값을 돌려주는 선택 팝업 3종 ($c.win.openPopup 을 await 로 수신, 취소는 빈 결과로 판단)
 * - 조회 결과(신규 / 수정 / 상장일 경과)에 따른 버튼 상태 일괄 제어 ($c.util.setButtonState)
 * - 입력 검증 통합 ($c.validate.validateDataCollect) + 통신이 필요한 중복 확인·날짜 선후 비교는 그 뒤에 별도 배치
 * - 신규·수정 공용 저장 통신 (executeDynamic, action 만 분기)
 *
 * 이 화면이 쓰는 프로젝트 의존 모듈
 * - $c.stf (getNewBzProcNo·getMessageParam) · $c.lc (fn_isProcess·fn_checkDoubleInput) 는 stf-front 의 업무공통(src/pcc/stf)이다.
 *   다른 프로젝트에서 참조할 때는 대응 공통이 있는지 확인하고 없으면 프로젝트 공통으로 대체한다.
 *
 * 변환 샘플과 달라진 곳
 * - 항목별 "빈값 → alert → focus → return false" 나열(필수 20·날짜 형식 4·길이 2 = 26건)을 validateDataCollect 한 건으로 통합했다.
 * - 신규 저장의 업무처리번호는 저장이 성공한 뒤에만 화면 상태값에 담는다(원본은 채번 직후 담아 저장 실패 시 수정 모드로 오판).
 *   통신이 필요한 중복입력 확인과 날짜 선후 비교(업무 조건)만 그 뒤에 남겼다.
 * - 조회 후 버튼 상태를 정하는 로직이 두 조회 함수에 복사돼 있던 것을 setFormState 하나로 모았다.
 * - 팝업 결과를 빈값 확인 없이 쓰던 곳에 취소(빈 결과) 처리를 넣었다.
 * - 사무관리회사 팝업이 돌려준 법인코드(isurCd)를 원본 fn_SetParBzAdmComNm 의 의도대로 bzAdmComIsurCd 에 담는다.
 * - 신규 진입 시 버튼 상태를 insert 로 초기화한다(원본은 종목을 고르기 전까지 전 버튼 활성).
 * - 미사용 전역(vScrenTpCD·rowPos·mktTpCd·fn_GetPar/fn_SetPar)·미참조 함수(fn_SetParInstCd·fn_SetParBzAdmComNm)·console.log 를 삭제했다.
 * - setCommonCode 옵션을 공통 규약({ code, compID, firstRow })으로 맞췄다. 코드 조회 URL 은 공통(COMMON_CODE_INFO)이 보유한다.
 *
 * 복사해서 쓰는 순서
 * 1. 파일명과 meta_screenId 를 실제 화면ID 로 변경
 * 2. dma_item·dma_in 키와 입력 마크업을 업무 항목으로 교체
 * 3. 각 통신의 action 경로를 실 API 로 교체
 * 4. 팝업 경로·반환 키 이름을 실제 선택 팝업에 맞게 교체
 * 5. validate 의 fields 와 BTN_MAP 을 업무 항목·버튼에 맞게 교체
 */


///////// 1. 변수 및 선언 영역 /////////

scwin.screenId = "ULDSTF05403";

// 부모 화면에서 넘겨받는 값
scwin.bzProcsNo = "";       // 업무처리번호 — 비어 있으면 신규, 있으면 수정
scwin.secugrpId = "";       // 증권그룹ID

// 화면 상태값
scwin.isurCd = "";          // 종목 선택 팝업이 돌려준 발행기관코드 (신규 저장 시 사용)
scwin.trJob = "";           // 처리구분 I: 저장, U: 수정
scwin.curDate = "";         // 서버 현재일 (yyyyMMdd)

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
scwin.BTN_MAP = {
    save : "btn_Save",      // [저장]
    modify : "btn_Update",  // [수정]
    guide : "btn_Dscl"      // [안내문작성]
};


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 11
 * @description 페이지로드
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        // 초기화 함수
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05403.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 11
 * @description 초기화. 공통코드를 채우고 부모 파라미터로 신규·수정을 가른 뒤, 수정이면 상세를 조회한다.
 *
 * 부모는 openPopup 의 3번째 인자를 { pData : { clickBzProcsNo, vSecugrpID } } 로 한 겹 감싸 넘긴다.
 * 평면으로 넘기는 부모라면 $c.data.getParameter() 로 전체를 받아 키를 바로 읽는다(ULDSTF07404 참조).
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 받는 파라미터 이름과 감싸는 키(pData)
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
    scwin.curDate = $c.date.getServerDateTime();

    // 공통코드 — 셀렉트박스를 먼저 채워야 조회 결과가 코드값으로 표시된다.
    await scwin.setCommonCode();

    // openPopup 의 3번째 인자로 넘어온 값
    const param = $c.data.getParameter("pData") ?? {};

    scwin.bzProcsNo = param.clickBzProcsNo ?? "";
    scwin.secugrpId = param.vSecugrpID ?? "";

    // 신규면 조회할 것이 없다. 종목을 고르면 예비심사 정보로 폼을 채운다.
    if ($c.util.isEmpty(scwin.bzProcsNo)) {
        scwin.setFormState();
        return;
    }

    await scwin.selectOne();
};

/**
 * @method
 * @name scwin.setCommonCode
 * @author Inswave
 * @date 2026. 09. 11
 * @description 공통코드 조회 — 투자기구종류 셀렉트박스를 채운다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - code 와 compID
 * @param
 * @returns
 * @hidden N
*/
scwin.setCommonCode = async function () {
    const codeOptions = [{
        code : "INVSTORG_TP_CD",        // 01404-투자기구종류
        compID : "cmb_INVSTORG_TP_CD",
        firstRow : ["", ""]
    }];

    await $c.data.setCommonCode(codeOptions);
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.img_ISU_CD_onclick
 * @author Inswave
 * @date 2026. 09. 11
 * @description 종목코드 돋보기 클릭. 수익증권 종목 선택 팝업에서 고른 종목의 예비심사 정보로 폼을 채운다.
 *
 * 값을 돌려주는 선택 팝업이라 결과가 비었는지로 취소를 판단한다.
 * 예비심사 업무처리번호가 없는 종목은 진행할 수 없으므로 버튼을 잠근다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - openPopup 의 팝업 경로, 팝업 크기, 넘길 파라미터, 반환 키 이름
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.img_ISU_CD_onclick = async function (e) {
    try {
        const options = {
            id : "ULDSTF05012",
            popupName : "수익증권종목 선택",
            width : 600,
            height : 640,
            frameModal : "top"
        };

        const param = {
            secugrpId : scwin.secugrpId,
            searchTyp : "SLC",
            mktTpCd : "1"           // 거래시장구분 1: 유가, 2: 코스닥
        };

        const result = await $c.win.openPopup("/ui/lst/common/ULDSTF05012.xml", options, param);

        // 선택 없이 닫으면 결과가 없다.
        if ($c.util.isEmpty(result)) return;

        // 팝업이 돌려준 값을 우선 보여 준다. 예비심사 조회가 성공하면 dma_item 전체가 조회 결과로 덮인다.
        // (단축코드 칸에 isuNm 을 넣는 것은 원본 그대로다 — 팝업 반환 키를 확인해 맞춘다)
        txb_ISU_CD.setValue(result.isuCd);
        txb_ISU_SRT_CD.setValue(result.isuNm);
        scwin.isurCd = result.isurCd;

        // 예비심사 업무처리번호가 없으면 예비심사 정보를 가져올 수 없다.
        if ($c.util.isEmpty(result.bzProcsNo)) {
            await $c.win.alert("예비심사의 업무처리번호가 없어 실행할수 없습니다.");
            $c.util.setButtonState("grp_btnBox", "error", scwin.BTN_MAP);
            img_ISU_CD.setDisabled(true);
            return;
        }

        await scwin.selectPrervw(result.bzProcsNo);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05403.img_ISU_CD_onclick" });
    }
};

/**
 * @event
 * @name scwin.img_TRST_INST_CD_onclick
 * @author Inswave
 * @date 2026. 09. 11
 * @description 수탁회사 돋보기 클릭. 기관 선택 팝업에서 고른 기관의 코드·명을 채운다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - openPopup 의 팝업 경로, 팝업 크기, 반환 키 이름
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.img_TRST_INST_CD_onclick = async function (e) {
    try {
        const options = {
            id : "ULDSTF92011",
            popupName : "기관 선택",
            width : 500,
            height : 700,
            frameModal : "top"
        };

        const result = await $c.win.openPopup("/ui/lst/common/ULDSTF92011.xml", options);

        // 선택 없이 닫으면 결과가 없다.
        if ($c.util.isEmpty(result)) return;

        txb_TRST_INST_CD.setValue(result.instCd);
        txb_TRST_INST_NM.setValue(result.instNm);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05403.img_TRST_INST_CD_onclick" });
    }
};

/**
 * @event
 * @name scwin.img_BZ_ADM_COM_NM_onclick
 * @author Inswave
 * @date 2026. 09. 11
 * @description 사무관리회사 돋보기 클릭. 법인 선택 팝업에서 고른 법인의 코드·명을 채운다.
 *
 * 법인코드(bzAdmComIsurCd)는 화면에 보이지 않지만 저장 전문에 실리므로 DataMap 에 직접 담는다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - openPopup 의 팝업 경로, 팝업 크기, 넘길 파라미터, 반환 키 이름
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.img_BZ_ADM_COM_NM_onclick = async function (e) {
    try {
        const options = {
            id : "ULDSTF05011",
            popupName : "법인 선택",
            width : 500,
            height : 700,
            frameModal : "top"
        };

        const param = {
            strTpCd : "KSQ_EXEM"
        };

        const result = await $c.win.openPopup("/ui/lst/common/ULDSTF05011.xml", options, param);

        // 선택 없이 닫으면 결과가 없다.
        if ($c.util.isEmpty(result)) return;

        dma_item.set("bzAdmComIsurCd", result.isurCd);      // 법인코드
        txb_BZ_ADM_COM_NM.setValue(result.comNm);           // 법인명
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05403.img_BZ_ADM_COM_NM_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_Save_onclick
 * @author Inswave
 * @date 2026. 09. 11
 * @description 저장 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_Save_onclick = async function (e) {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05403.btn_Save_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_Update_onclick
 * @author Inswave
 * @date 2026. 09. 11
 * @description 수정 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_Update_onclick = async function (e) {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05403.btn_Update_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_Dscl_onclick
 * @author Inswave
 * @date 2026. 09. 11
 * @description 안내문작성 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_Dscl_onclick = async function (e) {
    try {
        await scwin.writeDscl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05403.btn_Dscl_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_Close_onclick
 * @author Inswave
 * @date 2026. 09. 11
 * @description 닫기 버튼 클릭. 팝업을 닫는다.
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_Close_onclick = function (e) {
    try {
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05403.btn_Close_onclick" });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.selectPrervw
 * @author Inswave
 * @date 2026. 09. 11
 * @description 종목의 예비심사 정보를 조회해 dma_item 에 담고, 결과에 맞춰 버튼 상태를 정한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - action 경로, 요청 파라미터
 * @param {String} prelmBzProcsNo 예비심사 업무처리번호
 * @returns
 * @hidden N
*/
scwin.selectPrervw = async function (prelmBzProcsNo) {
    dma_item.setEmptyValue();

    const sbmOptions = {
        id : "sbm_selectPrervw",
        method : "get",
        action : "/api/listing/lstproc/beneficiary-cert/newlisting/select-prervw",
        target : "dma_item=body",
        isProcessMsg : false
    };

    const requestData = {
        bzProcsNo : prelmBzProcsNo
    };

    // 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다.
    // 여기서 잡지 않으므로 오류가 나면 아래 처리는 실행되지 않는다.
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);

    if (!result.responseJSON?.success) return;

    scwin.setFormState();
};

/**
 * @method
 * @name scwin.selectOne
 * @author Inswave
 * @date 2026. 09. 11
 * @description 업무처리번호로 상세를 조회해 dma_item 에 담고, 결과에 맞춰 버튼 상태를 정한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - action 경로, 요청 파라미터
 * @param
 * @returns
 * @hidden N
*/
scwin.selectOne = async function () {
    dma_item.setEmptyValue();

    const sbmOptions = {
        id : "sbm_selectOne",
        method : "get",
        action : "/api/listing/lstproc/beneficiary-cert/newlisting/select-one",
        target : "dma_item=body",
        isProcessMsg : false
    };

    const requestData = {
        bzProcsNo : scwin.bzProcsNo
    };

    // 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다.
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);

    if (!result.responseJSON?.success) return;

    scwin.setFormState();
};

/**
 * @method
 * @name scwin.saveNewListing
 * @author Inswave
 * @date 2026. 09. 11
 * @description 신규상장 정보를 저장(I) 또는 수정(U)한다. 완료 후 부모 목록을 재조회하고 상세를 다시 조회한다.
 *
 * 요청 DataMap(dma_in)은 화면 DataMap(dma_item)을 그대로 복사한 뒤 화면에 없는 값만 덧붙인다.
 * 신규·수정은 전문이 같고 action 만 다르므로 한 함수에서 분기한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - action 경로, 화면에 없는 고정값
 * @param {String} trJob 처리구분 I: 저장, U: 수정
 * @returns
 * @hidden N
*/
scwin.saveNewListing = async function (trJob) {
    dma_in.setEmptyValue();
    dma_in.setJSON(dma_item.getJSON());

    // 조회 결과에 없으면 팝업·부모에서 받아 둔 값을 쓴다.
    dma_in.set("bzProcsNo", $c.util.isEmpty(dma_item.get("bzProcsNo")) ? scwin.bzProcsNo : dma_item.get("bzProcsNo"));   // 업무처리번호 (신규는 save 가 채번해 dma_item 에 넣어 둔다)
    dma_in.set("isurCd", $c.util.isEmpty(dma_item.get("isurCd")) ? scwin.isurCd : dma_item.get("isurCd"));               // 발행기관코드
    dma_in.set("secugrpId", $c.util.isEmpty(dma_item.get("secugrpId")) ? scwin.secugrpId : dma_item.get("secugrpId"));   // 증권그룹ID
    dma_in.set("listMethdTpCd", "4");       // 상장방식유형 4: 신규상장
    dma_in.set("isuRsnContn", "신규상장");  // 발행사유

    const svcId = (trJob === "I") ? "insert" : "update";

    const sbmOptions = {
        id : "sbm_saveNewListing",
        method : "post",
        action : "/api/listing/lstproc/beneficiary-cert/newlisting/" + svcId,
        mediatype : "application/json",
        ref : "dma_in",
        isProcessMsg : false
    };

    // 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다.
    const result = await $c.sbm.executeDynamic(sbmOptions);

    if (!result.responseJSON?.success) return;

    // 저장이 성공한 뒤에야 수정 모드가 된다.
    scwin.bzProcsNo = dma_in.get("bzProcsNo");

    scwin.refreshParent();

    // "com_complete_0096": "$[0] 되었습니다."
    await $c.win.alert($c.data.getMessage("com_complete_0096", (trJob === "I") ? "저장" : "수정"));

    await scwin.selectOne();
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.setFormState
 * @author Inswave
 * @date 2026. 09. 11
 * @description 신규·수정·상장일 경과에 따라 종목 검색 가능 여부와 버튼 상태를 정한다.
 *
 * 조회가 끝날 때마다 부르므로 상태 판정을 한 곳에 모아 둔다.
 *  - 신규(업무처리번호 없음)      : [저장]만 활성, 종목 검색 가능
 *  - 수정(상장일이 현재일 이후)   : [수정]·[안내문작성] 활성, 종목 검색 잠금
 *  - 상장일 경과                  : 전 버튼 잠금, 종목 검색 잠금
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 상태 판정 기준 항목
 * @param
 * @returns
 * @hidden N
*/
scwin.setFormState = function () {
    const isNew = $c.util.isEmpty(scwin.bzProcsNo);

    // 종목 검색은 신규일 때만 허용한다. 수정은 종목을 바꿀 수 없다.
    img_ISU_CD.setDisabled(!isNew);

    if (isNew) {
        $c.util.setButtonState("grp_btnBox", "insert", scwin.BTN_MAP);
        return;
    }

    // 상장일이 지나지 않은 건만 수정할 수 있다. 지난 건은 전부 잠근다.
    const status = (edt_LIST_DD.getValue() > scwin.curDate) ? "update" : "error";

    $c.util.setButtonState("grp_btnBox", status, scwin.BTN_MAP);
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 09. 11
 * @description 저장·수정 전 입력값을 검증한다.
 *
 * 필수·날짜 형식·길이는 gcc 공통 검증 $c.validate.validateDataCollect 로 본다
 * (실패 시 표준 alert 과 대상 포커스를 공통이 처리, async 라 await 필요).
 * 읽기전용 항목(종목·수탁회사)은 focus 옵션으로 돋보기 버튼에 포커스를 준다.
 * 통신이 필요한 중복입력 확인과 날짜 선후 비교는 업무 조건이라 공통 검증 뒤에 별도로 본다.
 *
 * 비고의 byte 한도는 공통 검증 기준(UTF-8, 한글 3byte)으로 잰다. 원본(한글 2byte)보다 한글 입력 허용량이 줄어드니
 * DB 컬럼 기준에 맞춰 maxLengthB 값을 조정한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - options.fields 검증 항목 (키 = 컴포넌트 ID)
 * @param
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
*/
scwin.validate = async function () {
    const options = {
        validateType : "alert",     // alert|mark|all
        checkType : "single",       // single|multi
        fields : {
            txb_ISU_CD : { required : true, message : "[종목]을 선택하세요.", focus : "img_ISU_CD", name : "종목" },
            txb_ISU_SRT_CD : { required : true, name : "종목단축코드" },
            txb_COM_NM : { required : true, name : "위탁회사명" },
            txb_ISU_KOR_NM : { required : true, name : "한글종목명" },
            txb_ISU_KOR_ABBRV : { required : true, name : "한글종목약명" },
            txb_ISU_ENG_NM : { required : true, name : "영문종목명" },
            txb_ISU_ENG_ABBRV : { required : true, name : "영문종목약명" },
            txb_TRST_INST_CD : { required : true, message : "[수탁회사]를 선택하세요.", focus : "img_TRST_INST_CD", name : "수탁회사" },
            cmb_INVSTORG_TP_CD : { required : true, name : "투자기구종류" },
            edt_ISU_DD : { required : true, format : "date", name : "발행일" },
            edt_LIST_DD : { required : true, format : "date", name : "상장일" },
            edt_TRST_ESTB_DD : { required : true, format : "date", name : "신탁설정일" },
            edt_TRST_END_DD : { required : true, format : "date", name : "신탁만료일" },
            edt_TRST_ORGN_VAL : { required : true, name : "신탁원본액" },
            edt_TOT_STKCNT : { required : true, maxLength : 14, name : "수익증권총좌수" },
            edt_PARVAL : { required : true, name : "1좌당원본액" },
            edt_ISU_PRC : { required : true, name : "1좌당공모발행가액" },
            txb_TRST_CALC_PD_CONTN : { required : true, name : "신탁계산기간" },
            txb_ISU_BNDUNIT_NM : { required : true, name : "발행권종" },
            txb_PROFT_DISTR_PAY_TM_CONTN : { required : true, name : "이익등의분배" },
            txa_REMK : { maxLengthB : 2000, name : "비고 및 참고사항" }
        }
    };

    if (!await $c.validate.validateDataCollect(panel_Item, options)) return false;

    // 신규 저장은 같은 종목이 이미 신규상장 처리 중인지 서버에 확인한다 (통신이 필요해 공통 검증으로 옮기지 않는다).
    // 업무공통의 인자명은 isurCd 이지만 원본대로 종목코드를 넘긴다 — 서버 API 규격을 확인해 맞춘다.
    if (scwin.trJob === "I" && await $c.lc.fn_checkDoubleInput(txb_ISU_CD.getValue())) return false;

    // 상장일은 현재일 이후여야 한다.
    if (scwin.curDate >= edt_LIST_DD.getValue()) {
        await $c.win.alert("[상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }

    // 신탁설정일은 신탁만료일보다 앞서야 한다.
    if (Number(edt_TRST_ESTB_DD.getValue()) >= Number(edt_TRST_END_DD.getValue())) {
        await $c.win.alert("[신탁설정일]은 [신탁만료일]보다 작아야 합니다. 다시 입력해주세요");
        edt_TRST_ESTB_DD.focus();
        return false;
    }

    return true;
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 09. 11
 * @description 신규 저장. 검증과 확인을 거친 뒤 업무처리번호를 채번해 저장한다.
 *
 * 순서가 중요하다. 먼저 입력값을 검증하고, 사용자 확인을 받은 다음, 마지막에 채번한다.
 * 채번을 먼저 하면 취소한 건에도 번호가 소비된다.
 * @param
 * @returns
 * @hidden N
*/
scwin.save = async function () {
    scwin.trJob = "I";

    if (!await scwin.validate()) return;

    // "저장하시겠습니까?" 확인 — 업무공통 MSG-A006
    if (!await $c.lc.fn_isProcess(scwin.trJob)) return;

    // 신규 업무처리번호 채번 (14자리). 저장이 성공하기 전에는 화면 상태값(scwin.bzProcsNo)에 넣지 않는다.
    // 미리 넣으면 저장 실패 후에도 수정 모드로 판정돼 [저장]이 잠긴다.
    const newBzProcsNo = await $c.stf.getNewBzProcNo();

    if ($c.str.getByteLength(String(newBzProcsNo)) !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }

    dma_item.set("bzProcsNo", newBzProcsNo);

    await scwin.saveNewListing(scwin.trJob);
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 09. 11
 * @description 수정. 검증과 확인을 거친 뒤 수정한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.update = async function () {
    scwin.trJob = "U";

    if (!await scwin.validate()) return;

    // "수정하시겠습니까?" 확인 — 업무공통 MSG-A006
    if (!await $c.lc.fn_isProcess(scwin.trJob)) return;

    await scwin.saveNewListing(scwin.trJob);
};

